#!/usr/bin/env node
const fs = require('fs');

const input = process.argv[2];
if (!input) {
  console.error('Usage: node sheikha-compiler.js file.shk');
  process.exit(1);
}

const src = fs.readFileSync(input, 'utf8');

const php = `<?php
// Generated by Sheikha Language Compiler
// لغة شيخة: طبقة حكم وتشغيل فوق PHP

final class SheikhaGeneratedRule
{
    public function run(): array
    {
        return [
            'بسم_الله' => 'بسم الله الرحمن الرحيم',
            'language' => 'Sheikha Language',
            'source' => ${JSON.stringify(src)},
            'rules' => [
                'لا ضرر ولا ضرار',
                'الصدق والبيان',
                'منع الاحتكار',
                'منع الغش',
                'التوثيق قبل التوسع'
            ],
            'status' => 'compiled_to_php'
        ];
    }
}
`;
fs.writeFileSync(input.replace(/\.shk$/, '.php'), php);
console.log('SHEIKHA_LANGUAGE_COMPILED=' + input.replace(/\.shk$/, '.php'));
